mapper.select:
SELECT b.id, b.category_id, c.name AS categoryName, b.title, b.author, b.isbn, b.price, b.stock, b.status, b.cover_url, b.description, b.created_at FROM book b LEFT JOIN category c ON c.id = b.category_id
(b.title LIKE CONCAT('%', #{kw}, '%') OR b.author LIKE CONCAT('%', #{kw}, '%') OR b.isbn LIKE CONCAT('%', #{kw}, '%'))
AND b.status = #{status}
AND b.category_id = #{categoryId}
ORDER BY b.id DESC LIMIT #{limit} OFFSET #{offset}

sql.where:
status = 'ON_SHELF'

  AND (title LIKE CONCAT('%', #{kw}, '%')
  OR author LIKE CONCAT('%', #{kw}, '%')
  OR isbn LIKE CONCAT('%', #{kw}, '%'))


  AND category_id IN (
    SELECT id FROM category
    WHERE id = #{categoryId} OR parent_id = #{categoryId}
  )


  AND price >= #{priceMin}


  AND price <= #{priceMax}
